"""解析 PCCES 匯出的電子標單 XML（ETenderSheet，eTender.1.J.2004.D）。

金額一律用 Decimal：預算書的複價是整數元，浮點會在加總時累積誤差。

小計列（itemKind=subtotal）不只頂層那一列總計，任何一層都可能有（PCX-003，實案 218 列）：
1. 母項複價＝子項加總，但不含小計子項，否則同一筆錢算兩次。
2. 小計列有 MathML 時＝引用各列複價相加（實案「小計(壹.一~壹.二)」）。
3. 其餘小計列＝同層排在它前面、不是小計的各列加總；頂層最後那列總計就是頂層加總。
   「上一個小計之後」那種算法在實案「統包施工費合計」對不上，這條才全中。
"""

from __future__ import annotations

import re
import xml.etree.ElementTree as ET
from dataclasses import dataclass, field
from decimal import ROUND_HALF_UP, Decimal
from pathlib import Path
from typing import Callable, Iterator, Sequence

NS = "{http://pcstd.pcc.gov.tw/2003/eTender}"
MML = "{http://www.w3.org/1998/Math/MathML}"

# 小計列（含頂層「總計」）的複價是別列加總，加總時要排除，否則會算成兩倍
SUBTOTAL_KIND = "subtotal"
# 葉項複價＝數量×單價（leaf_amount）的種類，金額檢查逐列核對。變動單價項沒有單價分析，跟 general 同一條
# （實案 1103/1103 列成立）；寫入工具改值也照這條算（edit.EDITABLE_KINDS 同三種）
LEAF_KINDS = ("analysis", "general", "variablePrice")
_ITEM_KEY = re.compile(r"[0-9]+")


def item_path(parent_path: str, parent_no: str, own: str) -> str:
    """使用者看到的項次路徑。

    PCCES 的 itemNo 有兩種寫法：ArchEx001 每層只寫自己那段（壹／六／1 → 壹.六.1），
    實案每層就是完整項次（壹／壹.一／壹.一.1）。已經是上層路徑的延伸就直接用，
    以上層自己的 itemNo 開頭就把那段換成上層路徑，其餘才用「.」接上；兩種寫法混在同一份也照這三條走。
    """
    own = own.strip()
    if not own or not parent_path:
        return own
    if own.startswith(parent_path + "."):
        return own
    if parent_no and own.startswith(parent_no + "."):
        return parent_path + own[len(parent_no):]
    return f"{parent_path}.{own}"


def mathml_sum_refs(math, tag: Callable, kids: Callable, text: Callable) -> list[tuple[int, str]]:
    """小計列 MathML 引用的（正負號, itemKey）；只認 PCCES 樣本的寫法，其他丟 ValueError。

    樣本（實案）：<math><apply><plus/><apply><plus/><ci>2</ci><ci>128</ci></apply></apply></math>。
    `tag`／`kids`／`text` 取元素的本地名稱、子元素、文字，ElementTree 與 document.Node 共用這一支。
    相減、乘除、常數沒有樣本，PCCES 怎麼寫沒有依據，一律當看不懂。
    """

    def walk(n) -> list[tuple[int, str]]:
        name = tag(n)
        if name == "ci":
            t = (text(n) or "").strip()
            if not _ITEM_KEY.fullmatch(t):
                raise ValueError(f"引用「{t}」不是 itemKey")
            return [(1, t)]
        if name == "apply":
            ks = kids(n)
            if not ks or tag(ks[0]) != "plus" or kids(ks[0]):
                raise ValueError("只看得懂相加（plus）")
            return [r for k in ks[1:] for r in walk(k)]
        raise ValueError(f"看不懂 <{name}>")

    top = kids(math)
    if len(top) != 1:
        raise ValueError(f"最外層有 {len(top)} 個元素，樣本只有一個 apply")
    refs = walk(top[0])
    if not refs:
        raise ValueError("沒有引用任何列")
    return refs


def preceding_sum(siblings: Sequence, index: int, amount: Callable, is_subtotal: Callable) -> Decimal:
    """沒有 MathML 的小計列：同層排在它前面、不是小計的各列加總（見模組說明第 3 條）。"""
    return sum((amount(s) or Decimal(0) for s in siblings[:index] if not is_subtotal(s)), Decimal(0))


@dataclass
class PayItem:
    item_key: str
    item_no: str
    kind: str
    description: str
    unit: str
    quantity: Decimal | None
    price: Decimal | None
    amount: Decimal | None
    remark: str
    percent: Decimal | None
    ref_item_code: str
    children: list[PayItem] = field(default_factory=list)
    # 小計列有 MathML（資料庫是 budItemB）時引用的（正負號, itemKey）；沒有公式是 None
    sum_refs: list[tuple[int, str]] | None = None
    # 小計公式看不懂的原因；有值時 sum_refs 是 None，金額檢查會講明沒核對
    sum_refs_error: str = ""


@dataclass
class Budget:
    contract_no: str
    title: str
    procuring_entity: str
    location: str
    items: list[PayItem]
    resource_items: list[PayItem]
    total_amount: Decimal | None
    # DetailList 的 unitPriceDisplayDecimal／itemAmountDisplayDecimal。PCCES 先把單價
    # 進位到這個位數再乘數量（Class01 的 -243.58×100 記成 -24400），檢查時要照做
    price_decimals: int = 0
    amount_decimals: int = 0

    def computed_total(self) -> Decimal:
        return sum(
            (i.amount or Decimal(0) for i in self.items if i.kind != SUBTOTAL_KIND),
            Decimal(0),
        )

    def iter_items(self) -> Iterator[tuple[int, PayItem]]:
        """詳細表依原順序深度優先走訪，回傳（層級, 項目），頂層為 0。"""

        def walk(items: list[PayItem], level: int) -> Iterator[tuple[int, PayItem]]:
            for it in items:
                yield level, it
                yield from walk(it.children, level + 1)

        yield from walk(self.items, 0)


def find_items(
    budget: Budget, keyword: str | None = None, item_code: str | None = None
) -> list[tuple[list[PayItem], PayItem]]:
    """依名稱關鍵字（不分大小寫、子字串）或工項代碼前綴找詳細表的項目。

    回傳（上層鏈, 項目），上層鏈從頂層排到直屬上層，用來標出項目在哪一章。
    兩個條件都給時要同時符合。
    """
    kw = keyword.strip().lower() if keyword else None
    code = item_code.strip() if item_code else None
    hits: list[tuple[list[PayItem], PayItem]] = []

    def walk(items: list[PayItem], chain: list[PayItem]) -> None:
        for it in items:
            ok = True
            if kw is not None and kw not in it.description.lower():
                ok = False
            if code is not None and not it.ref_item_code.startswith(code):
                ok = False
            if ok:
                hits.append((list(chain), it))
            walk(it.children, chain + [it])

    if kw is None and code is None:
        raise ValueError("keyword 與 item_code 至少要給一個")
    walk(budget.items, [])
    return hits


def round_price(price: Decimal, price_decimals: int) -> Decimal:
    """四捨五入是遠離零：-243.58 進位到 0 位是 -244。"""
    return price.quantize(Decimal(1).scaleb(-price_decimals), ROUND_HALF_UP)


def leaf_amount(quantity: Decimal, price: Decimal, price_decimals: int, amount_decimals: int) -> Decimal:
    """葉項複價：單價先進位到 unitPriceDisplayDecimal 再乘數量，乘積進位到 itemAmountDisplayDecimal。

    金額檢查與寫入工具共用這一條，兩邊才不會各算各的。
    """
    p = round_price(price, price_decimals)
    return (quantity * p).quantize(Decimal(1).scaleb(-amount_decimals), ROUND_HALF_UP)


def _text(el: ET.Element, tag: str) -> str:
    child = el.find(NS + tag)
    return (child.text or "").strip() if child is not None else ""


def _dec(el: ET.Element, tag: str) -> Decimal | None:
    s = _text(el, tag)
    return Decimal(s) if s else None


def _local(el: ET.Element) -> str:
    return el.tag.rsplit("}", 1)[-1]


def _pay_item(el: ET.Element) -> PayItem:
    it = PayItem(
        item_key=el.get("itemKey", "").strip(),
        item_no=el.get("itemNo", "").strip(),
        kind=el.get("itemKind", "").strip(),
        description=_text(el, "Description"),
        unit=_text(el, "Unit"),
        quantity=_dec(el, "Quantity"),
        price=_dec(el, "Price"),
        amount=_dec(el, "Amount"),
        remark=_text(el, "Remark"),
        percent=_dec(el, "Percent"),
        ref_item_code=el.get("refItemCode", "").strip(),
        children=[_pay_item(c) for c in el.findall(NS + "PayItem")],
    )
    math = el.find(MML + "math")
    if it.kind == SUBTOTAL_KIND and math is not None:
        try:
            it.sum_refs = mathml_sum_refs(math, _local, list, lambda e: e.text)
        except ValueError as exc:
            it.sum_refs_error = str(exc)
    return it


def parse_etender(path: str | Path) -> Budget:
    root = ET.parse(path).getroot()
    if root.tag != NS + "ETenderSheet":
        raise ValueError(f"不是 PCCES 電子標單 XML：根節點是 {root.tag}，應為 ETenderSheet")
    info = root.find(NS + "TenderInformation")
    detail = root.find(NS + "DetailList")
    resource = root.find(NS + "ResourceList")
    grand = root.find(NS + "GrandTotalInformation")
    return Budget(
        contract_no=(info.get("contractNo", "") if info is not None else "").strip(),
        title=_text(info, "ContractTitle") if info is not None else "",
        procuring_entity=_text(info, "ProcuringEntity") if info is not None else "",
        location=_text(info, "ContractLocation") if info is not None else "",
        items=[_pay_item(e) for e in detail.findall(NS + "PayItem")] if detail is not None else [],
        resource_items=[_pay_item(e) for e in resource.findall(NS + "PayItem")] if resource is not None else [],
        total_amount=_dec(grand, "TotalAmount") if grand is not None else None,
        price_decimals=int(detail.get("unitPriceDisplayDecimal", "0") or 0) if detail is not None else 0,
        amount_decimals=int(detail.get("itemAmountDisplayDecimal", "0") or 0) if detail is not None else 0,
    )


def _levels(items: list[PayItem], parent_path: str, parent_no: str):
    """（同層, 位置, 項目, 項次路徑, 上層路徑），先序走訪。"""
    for idx, it in enumerate(items):
        path = item_path(parent_path, parent_no, it.item_no)
        yield items, idx, it, path, parent_path
        yield from _levels(it.children, path, it.item_no)


def _subtotal_problem(siblings, idx, it: PayItem, where: str, by_key: dict[str, list[PayItem]]) -> str | None:
    if it.sum_refs_error:
        return f"{where}：小計公式{it.sum_refs_error}，沒有核對"
    if it.sum_refs is None:
        s = preceding_sum(siblings, idx, lambda x: x.amount, lambda x: x.kind == SUBTOTAL_KIND)
        return None if s == it.amount else f"{where}：同層前面各項加總 {s} ≠ 複價 {it.amount}"
    s = Decimal(0)
    for sign, key in it.sum_refs:
        hits = by_key.get(key, [])
        if len(hits) != 1:
            why = "詳細表沒有這一列" if not hits else f"有 {len(hits)} 列用這個號碼"
            return f"{where}：小計公式引用 itemKey {key}，{why}，沒有核對"
        s += sign * (hits[0].amount or Decimal(0))
    return None if s == it.amount else f"{where}：小計公式引用各列加總 {s} ≠ 複價 {it.amount}"


def check_consistency(budget: Budget) -> list[str]:
    """回傳金額對不起來的地方，空清單代表一致。小計列的規則見模組說明。"""
    problems: list[str] = []
    if budget.total_amount is not None and budget.computed_total() != budget.total_amount:
        problems.append(f"頂層加總 {budget.computed_total()} ≠ 總價 {budget.total_amount}")
    by_key: dict[str, list[PayItem]] = {}
    for _, it in budget.iter_items():
        by_key.setdefault(it.item_key, []).append(it)
    for siblings, idx, it, path, parent_path in _levels(budget.items, "", ""):
        if it.kind == SUBTOTAL_KIND:
            if it.amount is not None:
                where = f"{parent_path or '頂層'} 底下的「{it.description}」"
                p = _subtotal_problem(siblings, idx, it, where, by_key)
                if p:
                    problems.append(p)
        elif it.children and it.amount is not None:
            s = sum((c.amount or Decimal(0) for c in it.children if c.kind != SUBTOTAL_KIND), Decimal(0))
            if s != it.amount:
                problems.append(f"{path} {it.description}：子項加總（不含小計列）{s} ≠ 複價 {it.amount}")
        elif not it.children and it.kind in LEAF_KINDS:
            if None not in (it.quantity, it.price, it.amount):
                qp = leaf_amount(it.quantity, it.price, budget.price_decimals, budget.amount_decimals)
                if qp != it.amount:
                    problems.append(f"{path} {it.description}：數量×單價 {qp} ≠ 複價 {it.amount}")
    return problems
